module recovered_datapath(
    input  [7:0] a,
    input  [7:0] b,
    input  [1:0] sel,
    output [7:0] y
);

    reg [7:0] y_r;

    always @* begin
        case (sel)
            2'b00: y_r = a + b;
            2'b01: y_r = b - a;
            2'b10: y_r = a & b;
            2'b11: y_r = a | b;
            default: y_r = 8'b0;
        endcase
    end

    assign y = y_r;

endmodule

module recovered_datapath(
    input  [7:0] a,
    input  [7:0] b,
    input  [1:0] sel,
    output [7:0] y
);

    reg [8:0] wide_r;
    reg [7:0] y_r;

    always @* begin
        case (sel)
            2'b00: begin
                wide_r = {1'b0, a} + {1'b0, b};
                // BUG: instead of truncating to the low 8 bits (a+b mod 256),
                // the carry-out is folded into the result by shifting, leaking
                // internal carry state into the public output and breaking
                // modulo-256 wraparound semantics.
                y_r = wide_r[8:1];
            end
            2'b01: begin
                wide_r = {1'b0, a} - {1'b0, b};
                y_r = wide_r[8:1];
            end
            2'b10: y_r = a & b;
            2'b11: y_r = a | b;
            default: y_r = 8'b0;
        endcase
    end

    assign y = y_r;

endmodule

